		for _, cell := range cells {
			parts := strings.SplitN(cell, " / ", 2)
			key := task + "\x00" + parts[0] + "\x00" + parts[1]
			if runCounts[key] == 0 {
				b.WriteString(" n/a |")
				continue
			}
			fmt.Fprintf(b, " %d/%d |", passCounts[key], runCounts[key])
		}
		b.WriteString("\n")
	}
}

